// High fidelity weather panel for Open-Meteo data.
//
// Everything is drawn as responsive SVG that FrameOS rasterizes for the frame.
// Text uses native SVG <text> nodes; icons come from the "Weather icon set (JS)" app.


function esc(value) {
  return ('' + value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function textWidth(str, size) {
  return ('' + str).length * size * 0.58
}

function fitSize(str, size, maxWidth) {
  const w = textWidth(str, size)
  return w > maxWidth ? (size * maxWidth) / w : size
}

function text(str, x, y, size, color, weight, anchor) {
  const svgAnchor = anchor || 'start'
  const fontWeight = weight > size * 0.13 ? '700' : '600'
  return (
    '<text x="' + x.toFixed(2) + '" y="' + y.toFixed(2) + '"' +
    ' fill="' + esc(color) + '" font-family="PT Sans" font-size="' + size.toFixed(2) + '"' +
    ' font-weight="' + fontWeight + '" text-anchor="' + svgAnchor + '"' +
    ' dominant-baseline="alphabetic">' + esc(str) + '</text>'
  )
}

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v
}

function hexToRgb(hex) {
  const h = hex.charAt(0) === '#' ? hex.substring(1) : hex
  return [
    parseInt(h.substring(0, 2), 16),
    parseInt(h.substring(2, 4), 16),
    parseInt(h.substring(4, 6), 16),
  ]
}

function rgbToHex(r, g, b) {
  const to2 = (v) => {
    const s = Math.round(clamp(v, 0, 255)).toString(16)
    return s.length < 2 ? '0' + s : s
  }
  return '#' + to2(r) + to2(g) + to2(b)
}

function mix(hexA, hexB, t) {
  const a = hexToRgb(hexA)
  const b = hexToRgb(hexB)
  return rgbToHex(a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t)
}

// Temperature to color, anchored on celsius; fahrenheit values are converted.
const TEMP_STOPS = [
  [-15, '#7FA9F0'],
  [0, '#7CC4E8'],
  [10, '#8FD0A8'],
  [18, '#F2C94C'],
  [27, '#F2994A'],
  [38, '#EB5757'],
]

function tempColor(value, unit) {
  let c = value
  if (unit && unit.indexOf('F') >= 0) {
    c = ((value - 32) * 5) / 9
  }
  if (c <= TEMP_STOPS[0][0]) {
    return TEMP_STOPS[0][1]
  }
  for (let i = 1; i < TEMP_STOPS.length; i++) {
    if (c <= TEMP_STOPS[i][0]) {
      const t = (c - TEMP_STOPS[i - 1][0]) / (TEMP_STOPS[i][0] - TEMP_STOPS[i - 1][0])
      return mix(TEMP_STOPS[i - 1][1], TEMP_STOPS[i][1], t)
    }
  }
  return TEMP_STOPS[TEMP_STOPS.length - 1][1]
}

function parseIso(iso) {
  // "2026-01-18T22:15" -> parts; no Date object to stay deterministic.
  const datePart = iso.split('T')[0]
  const timePart = iso.split('T')[1] || '00:00'
  const d = datePart.split('-')
  const t = timePart.split(':')
  return {
    y: parseInt(d[0], 10),
    mo: parseInt(d[1], 10),
    d: parseInt(d[2], 10),
    h: parseInt(t[0], 10),
    mi: parseInt(t[1] || '0', 10),
  }
}

const DAY_NAMES = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT']
const MONTH_NAMES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC']

const I18N = {
