function langPack(language) {
  return I18N[language] || I18N.en
}

function label(p, key) {
  return langPack(p.language)[key] || I18N.en[key] || key
}

function dayName(language, index) {
  const pack = langPack(language)
  return (pack.days || DAY_NAMES)[index] || DAY_NAMES[index]
}

function monthName(language, index) {
  const pack = langPack(language)
  return (pack.months || MONTH_NAMES)[index] || MONTH_NAMES[index]
}

function translateCondition(language, code, fallback) {
  const pack = langPack(language)
  return (pack.conditions && pack.conditions['' + code]) || fallback
}

function dayOfWeek(y, mo, d) {
  // Sakamoto's algorithm, 0 = Sunday.
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
  let yy = y
  if (mo < 3) {
    yy -= 1
  }
  return (yy + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400) + t[mo - 1] + d) % 7
}

function fmtTemp(v) {
  const r = Math.round(v)
  return (r === 0 ? 0 : r) + '°'
}

function unitLetter(unit) {
  return ('' + (unit || '°C')).indexOf('F') >= 0 ? 'F' : 'C'
}

function fmtPrecip(v) {
  return Math.round(v * 10) / 10 + ''
}

function fmtClock(iso) {
  const p = iso.split('T')
  return p.length > 1 ? p[1] : iso
}

function iconFragment(iconSet, code, isDay, x, y, size) {
  if (!iconSet || !iconSet.icons) {
    return ''
  }
  const map = iconSet.map || {}
  const icons = iconSet.icons
  let key = map['' + code] || 'cloudy'
  if (!isDay && icons[key + '-night']) {
    key = key + '-night'
  }
  if (!icons[key]) {
    key = icons['cloudy'] ? 'cloudy' : ''
  }
  if (!key) {
    return ''
  }
  const vb = iconSet.viewBox || 64
  const s = size / vb
  return '<g transform="translate(' + x.toFixed(2) + ' ' + y.toFixed(2) + ') scale(' + s.toFixed(4) + ')">' + icons[key] + '</g>'
}

function conditionLabel(iconSet, code, language) {
  const fallback = iconSet && iconSet.labels && iconSet.labels['' + code] ? iconSet.labels['' + code] : label({ language: language }, 'code') + ' ' + code
  return translateCondition(language, code, fallback)
}

// ---------------------------------------------------------------------------
// Themes
// ---------------------------------------------------------------------------

function skyFor(code, isDay) {
  if (code >= 95) {
    return ['#252A40', '#4A5578']
  }
  if (code >= 71 && code <= 86 && code !== 80 && code !== 81 && code !== 82) {
    return isDay ? ['#5D7A9C', '#A9BFD6'] : ['#1F2A3F', '#44546F']
  }
  if (code >= 51) {
    return isDay ? ['#3E5C7A', '#7395B0'] : ['#141E2C', '#31445C']
  }
  if (code >= 45) {
    return isDay ? ['#6E7B8A', '#A3AEBA'] : ['#242B34', '#4A545F']
  }
  if (code >= 2) {
    return isDay ? ['#3E6FB0', '#84AED6'] : ['#161E38', '#35426A']
  }
  return isDay ? ['#2E6FD0', '#7FB8EE'] : ['#111834', '#2C3B6E']
}

function themeFor(code, isDay, lowContrast) {
  if (lowContrast) {
    return {
      flat: true,
      bgTop: '#FFFFFF',
      bgBottom: '#FFFFFF',
      text: '#111111',
      sub: '#3D3D3D',
      faint: '#8A8A8A',
      line: '#111111',
      grid: '#C8C8C8',
      rain: '#111111',
      areaFill: 'none',
      barSolid: '#111111',
    }
  }
  const sky = skyFor(code, isDay)
  return {
    flat: false,
    bgTop: sky[0],
    bgBottom: sky[1],
    text: '#FFFFFF',
    sub: 'rgba(255,255,255,0.78)',
    faint: 'rgba(255,255,255,0.45)',
    line: '#FFFFFF',
    grid: 'rgba(255,255,255,0.22)',
    rain: '#9BDCFF',
    areaFill: 'rgba(255,255,255,0.16)',
    barSolid: '',
  }
}

// ---------------------------------------------------------------------------
// Data extraction
// ---------------------------------------------------------------------------

function hourlySeries(forecast, count) {
  const hourly = forecast.hourly || {}
  const times = hourly.time || []
  const cur = forecast.current_weather || {}
  const nowIso = cur.time || (times.length ? times[0] : '')
  let start = 0
  for (let i = 0; i < times.length; i++) {
    if (times[i] >= nowIso.substring(0, 14) + '00') {
      start = i
      break
    }
    if (i === times.length - 1) {
      start = i
    }
  }
  const out = []
  for (let i = start; i < times.length && out.length < count; i++) {
    const p = parseIso(times[i])
    out.push({
      iso: times[i],
      hour: p.h,
      dow: dayOfWeek(p.y, p.mo, p.d),
      temp: (hourly.temperature_2m || [])[i],
      precip: (hourly.precipitation || [])[i] || 0,
      code: (hourly.weathercode || [])[i] || 0,
      wind: (hourly.windspeed_10m || [])[i],
      isDay: hourIsDay(p.h, forecast),
    })
  }
  return out
}

function hourIsDay(hour, forecast) {
  // Approximate day/night per hour from the first day's sunrise/sunset.
  const daily = forecast.daily || {}
  const sunrise = (daily.sunrise || [])[0]
  const sunset = (daily.sunset || [])[0]
  if (!sunrise || !sunset) {
    return hour >= 7 && hour < 20
  }
  const riseH = parseIso(sunrise).h
  const setH = parseIso(sunset).h
  return hour >= riseH && hour <= setH
}

function dailySeries(forecast, count) {
  const daily = forecast.daily || {}
  const times = daily.time || []
  const out = []
  for (let i = 0; i < times.length && out.length < count; i++) {
    const p = parseIso(times[i])
    out.push({
      iso: times[i],
      dow: dayOfWeek(p.y, p.mo, p.d),
      dayNum: p.d,
      min: (daily.temperature_2m_min || [])[i],
      max: (daily.temperature_2m_max || [])[i],
      precip: (daily.precipitation_sum || [])[i] || 0,
      code: (daily.weathercode || [])[i] || 0,
    })
  }
  return out
}

// ---------------------------------------------------------------------------
// Round panels
// ---------------------------------------------------------------------------

// A round panel shows only the circle inside its square (docs/scene-guide.md
// "Round panels"), 12 px in from the rim. On the panel's whole canvas that is
// this canvas's own circle; in a row of a split (the scene's stacked and full
// modes) the row says where it starts, as a share of the frame's height
// (roundTop), and the circle's centre is above or below the row's. Null on
// every other panel, which keeps its layout as it was.
function roundCircle(app, context, W, H) {
  if (!app.frame || !app.frame.round) {
    return null
  }
  if (context.round) {
    return { cx: W / 2, cy: H / 2, r: Math.min(W, H) / 2 - 12 }
  }
  const share = parseFloat('' + app.config.roundTop)
  const frameW = Number(app.frame.width) || W
  const frameH = Number(app.frame.height) || H
  if (!Number.isFinite(share) || Math.abs(frameW - W) > 2) {
    return null
  }
  return { cx: W / 2, cy: frameH / 2 - share * frameH, r: Math.min(frameW, frameH) / 2 - 12 }
}

// What the circle shows of the row at y: [left, right].
function chordAt(p, y) {
  const c = p.circle
  const dy = y - c.cy
  const half = Math.abs(dy) >= c.r ? 0 : Math.sqrt(c.r * c.r - dy * dy)
  return [Math.max(0, c.cx - half), Math.min(p.W, c.cx + half)]
}

// What a block from y0 down to y1 may use: the narrowest of its rows, the one
// farthest from the centre.
function chordBetween(p, y0, y1) {
  return chordAt(p, Math.abs(y0 - p.circle.cy) > Math.abs(y1 - p.circle.cy) ? y0 : y1)
}

// The left and right a block from y0 to y1 lays out between: the padding, and
// on a round panel the circle too.
function sidesBetween(p, y0, y1) {
  if (!p.circle) {
    return [p.pad, p.W - p.pad]
  }
  const span = chordBetween(p, y0, y1)
  return [Math.max(p.pad, span[0]), Math.min(p.W - p.pad, span[1])]
}

// ---------------------------------------------------------------------------
// Shared chrome
// ---------------------------------------------------------------------------

function backgroundSvg(p) {
  if (p.theme.flat) {
    return '<rect x="0" y="0" width="' + p.W + '" height="' + p.H + '" fill="' + p.theme.bgTop + '"/>'
  }
  return (
    '<linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="' + p.H + '">' +
    '<stop offset="0" stop-color="' + p.theme.bgTop + '"/>' +
    '<stop offset="1" stop-color="' + p.theme.bgBottom + '"/>' +
    '</linearGradient>' +
    '<rect x="0" y="0" width="' + p.W + '" height="' + p.H + '" fill="url(#bg)"/>'
  )
}

function headerSvg(p, title) {
  if (p.circle) {
    return roundHeaderSvg(p, title)
  }
  const parts = []
  const size = p.base
  const y = p.pad + size
  if (p.showLocation && p.locationName) {
    // The place shrinks to what the title on its right leaves it (its mixed
    // case runs narrower than textWidth's all-caps guess: half an em a letter).
    const room = Math.max(p.W - p.pad * 2 - textWidth(title, size * 0.82) - size, size * 4)
    const placeW = ('' + p.locationName).length * size * 0.5
    const placeSize = placeW > room ? (size * room) / placeW : size
    parts.push(text(p.locationName, p.pad, y, placeSize, p.theme.text, placeSize * 0.14, 'start'))
    parts.push(text(title, p.W - p.pad, y, size * 0.82, p.theme.sub, size * 0.1, 'end'))
  } else {
    parts.push(text(title, p.pad, y, size * 0.9, p.theme.sub, size * 0.12, 'start'))
  }
  return { svg: parts.join(''), bottom: y + size * 0.6 }
}

// The header on a round panel: centred, the place on a line of its own and
// the date under it, lowered to where the circle is as wide as the first line
// and each line fitted to the circle where it is.
function roundHeaderSvg(p, title) {
  const parts = []
  const size = p.base
  const lines = []
  if (p.showLocation && p.locationName) {
    lines.push({ str: p.locationName, size: size, color: p.theme.text, weight: size * 0.14 })
    lines.push({ str: title, size: size * 0.82, color: p.theme.sub, weight: size * 0.1 })
  } else {
    lines.push({ str: title, size: size * 0.9, color: p.theme.sub, weight: size * 0.12 })
  }
  const c = p.circle
  const want = Math.min(textWidth(lines[0].str, lines[0].size) + size, c.r * 1.3)
  let top = Math.max(p.pad, c.cy - Math.sqrt(Math.max(0, c.r * c.r - (want * want) / 4)))
  let baseline = top
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    baseline = top + line.size * 0.85
    const span = chordBetween(p, top, baseline + line.size * 0.2)
    const fitted = fitSize(line.str, line.size, span[1] - span[0] - size * 0.5)
    parts.push(text(line.str, c.cx, baseline, fitted, line.color, line.weight * (fitted / line.size), 'middle'))
    top = baseline + line.size * 0.4
  }
  return { svg: parts.join(''), bottom: baseline + size * 0.6 }
}

function windArrow(x, y, r, deg, color, lw) {
  // Arrow points in the direction the wind blows toward.
  const d = 'M0 ' + (-r).toFixed(2) + ' L' + (r * 0.62).toFixed(2) + ' ' + (r * 0.85).toFixed(2) +
    ' L0 ' + (r * 0.35).toFixed(2) + ' L' + (-r * 0.62).toFixed(2) + ' ' + (r * 0.85).toFixed(2) + ' Z'
  return (
    '<g transform="translate(' + x.toFixed(2) + ' ' + y.toFixed(2) + ') rotate(' + ((deg + 180) % 360).toFixed(1) + ')">' +
    '<path d="' + d + '" fill="' + color + '" stroke="' + color + '" stroke-width="' + lw +
    '" stroke-linejoin="round"/></g>'
  )
}

// ---------------------------------------------------------------------------
// Current conditions panel
// ---------------------------------------------------------------------------

function renderCurrent(p) {
  const parts = []
  const cur = p.forecast.current_weather || {}
  const units = p.forecast.current_weather_units || {}
  const daily = p.forecast.daily || {}
  const isDay = cur.is_day === 1
  const compact = p.H < 240 || (p.H < 300 && !p.showDetails)

  let top = p.pad
  if (p.showLocation) {
    const dateIso = (cur.time || p.weather.date || '').substring(0, 10)
    let title = ''
    if (dateIso) {
      const dp = parseIso(dateIso)
      title = dayName(p.language, dayOfWeek(dp.y, dp.mo, dp.d)) + ' ' + dp.d + ' ' + monthName(p.language, dp.mo - 1)
    }
    const h = headerSvg(p, title)
    parts.push(h.svg)
    top = h.bottom
  }

  const detailsH = p.showDetails && !compact ? clamp(p.H * 0.2, 54, 92) : 0
  const feelsH = compact ? p.base * 1.4 : p.base * 1.9
  const condH = compact ? p.base * 1.7 : p.base * 2.2

  const heroTop = top
  // On a round panel the last row ends where the circle is still 1.5 r wide.
  const floor = p.circle ? Math.min(p.H - p.pad, p.circle.cy + p.circle.r * 0.66) : p.H - p.pad
  const heroBottom = floor - detailsH - condH - feelsH
  const heroH = Math.max(40, heroBottom - heroTop)
  let iconSize = clamp(Math.min(heroH * 0.9, p.W * 0.36), 34, 260)
  let tempSize = clamp(Math.min(heroH * 0.95, p.W * 0.38), 30, 220)
  const tempStr = fmtTemp(cur.temperature || 0)
  let gapHero = iconSize * 0.12
  let tempW = textWidth(tempStr, tempSize)
  let heroW = iconSize + gapHero + tempW
  if (p.circle) {
    // As wide as the circle is at the hero's top or bottom, whichever is narrower.
    const sides = sidesBetween(p, heroTop, heroTop + heroH)
    const room = sides[1] - sides[0]
    if (heroW > room) {
      const k = room / heroW
      iconSize *= k
      tempSize *= k
      gapHero *= k
      tempW *= k
      heroW = room
    }
  }
  const heroX = (p.W - heroW) / 2
  const heroMidY = heroTop + heroH / 2
  parts.push(iconFragment(p.icons, cur.weathercode || 0, isDay, heroX, heroMidY - iconSize / 2, iconSize))
  const tempBase = heroMidY + tempSize * 0.42
  parts.push(text(tempStr, heroX + iconSize + gapHero, tempBase, tempSize, p.theme.text, tempSize * 0.15, 'start'))

  const condY = heroBottom + condH * 0.72
  const condStr = conditionLabel(p.icons, cur.weathercode || 0, p.language)
  const condSides = sidesBetween(p, condY - condH * 0.7, condY + condH * 0.2)
  const condSize = p.circle ? fitSize(condStr, condH * 0.82, condSides[1] - condSides[0]) : condH * 0.82
  parts.push(text(condStr, p.W / 2, condY, condSize, p.theme.text, condH * 0.11, 'middle'))

  const bits = []
  const apparent = currentApparent(p.forecast)
  if (apparent !== null) {
    bits.push(label(p, 'feels') + ' ' + fmtTemp(apparent))
  }
  if ((daily.temperature_2m_max || []).length) {
    bits.push('H ' + fmtTemp(daily.temperature_2m_max[0]) + ' L ' + fmtTemp(daily.temperature_2m_min[0]))
  }
  if (bits.length) {
    const feelsStr = bits.join(' · ')
    const feelsY = condY + feelsH * 0.76
    const feelsSides = sidesBetween(p, feelsY - feelsH * 0.55, feelsY + feelsH * 0.15)
    const feelsSize = p.circle ? fitSize(feelsStr, feelsH * 0.64, feelsSides[1] - feelsSides[0]) : feelsH * 0.64
    parts.push(text(feelsStr, p.W / 2, feelsY, feelsSize, p.theme.sub, feelsH * 0.08, 'middle'))
  }

  if (detailsH > 0) {
    parts.push(renderDetailCells(p, cur, units, daily, floor - detailsH, detailsH))
  }
  return parts.join('')
}

function currentApparent(forecast) {
  const hourly = forecast.hourly || {}
  const cur = forecast.current_weather || {}
  const times = hourly.time || []
  const apparent = hourly.apparent_temperature || []
  if (!times.length || !apparent.length || !cur.time) {
    return null
  }
  const key = cur.time.substring(0, 14) + '00'
  for (let i = 0; i < times.length; i++) {
    if (times[i] === key) {
      return apparent[i]
    }
  }
  return null
}

function renderDetailCells(p, cur, units, daily, top, height) {
  const parts = []
  const cells = []
  const windUnit = (units.windspeed || 'km/h').toUpperCase()
  cells.push({
    label: label(p, 'wind'),
    value: Math.round(cur.windspeed || 0) + ' ' + windUnit,
    arrow: cur.winddirection,
  })
  const dailyUnits = p.forecast.daily_units || {}
  const precip = (daily.precipitation_sum || [])[0]
  cells.push({
    label: label(p, 'precip'),
    value: (precip === undefined ? '0' : Math.round(precip * 10) / 10) + ' ' + (dailyUnits.precipitation_sum || 'mm').toUpperCase(),
  })
  const sunrise = (daily.sunrise || [])[0]
  const sunset = (daily.sunset || [])[0]
  if (sunrise) {
    cells.push({ label: label(p, 'sunrise'), value: fmtClock(sunrise) })
  }
  if (sunset) {
    cells.push({ label: label(p, 'sunset'), value: fmtClock(sunset) })
  }

  const sides = sidesBetween(p, top, top + height)
  const left = sides[0]
  parts.push(
    '<line x1="' + left.toFixed(2) + '" y1="' + top.toFixed(2) + '" x2="' + sides[1].toFixed(2) + '" y2="' + top.toFixed(2) +
    '" stroke="' + p.theme.grid + '" stroke-width="1"/>'
  )

  const n = cells.length
  const cellW = (sides[1] - left) / n
  const innerW = cellW * 0.86
  const labelBase = clamp(height * 0.16, 7, 12)
  const valueBase = clamp(height * 0.26, 9, 19)
  for (let i = 0; i < n; i++) {
    const cx = left + cellW * (i + 0.5)
    const cell = cells[i]
    const labelSize = fitSize(cell.label, labelBase, innerW)
    parts.push(text(cell.label, cx, top + height * 0.34, labelSize, p.theme.faint, labelSize * 0.13, 'middle'))
    const hasArrow = cell.arrow !== undefined
    const midY = top + height * 0.68
    let valueSize = fitSize(cell.value, valueBase, hasArrow ? innerW - valueBase * 0.9 : innerW)
    const valueW = textWidth(cell.value, valueSize)
    const arrowW = hasArrow ? valueSize * 0.85 : 0
    const groupX = cx - (valueW + arrowW) / 2
    if (hasArrow) {
      parts.push(windArrow(groupX + arrowW * 0.36, midY, valueSize * 0.34, cell.arrow || 0, p.theme.sub, 1))
    }
    parts.push(text(cell.value, groupX + arrowW, midY + valueSize * 0.36, valueSize, p.theme.text, valueSize * 0.12, 'start'))
    if (i > 0) {
      const lx = left + cellW * i
      parts.push(
        '<line x1="' + lx.toFixed(2) + '" y1="' + (top + height * 0.22).toFixed(2) + '" x2="' + lx.toFixed(2) +
        '" y2="' + (top + height * 0.82).toFixed(2) + '" stroke="' + p.theme.grid + '" stroke-width="1"/>'
      )
    }
  }
  return parts.join('')
}

// ---------------------------------------------------------------------------
// Hourly forecast panel
// ---------------------------------------------------------------------------

// Where the hourly rows end: the padding, and on a round panel high enough
// that the circle is still 1.55 r wide there.
function hourlyFloor(p) {
  return p.circle ? Math.min(p.H - p.pad, p.circle.cy + p.circle.r * 0.63) : p.H - p.pad
}

function renderHourly(p) {
  // The chart's narrowest row is its last, at the floor.
  const sides = sidesBetween(p, hourlyFloor(p), hourlyFloor(p))
  const availW = sides[1] - sides[0]
  const wanted = clamp(p.hours, 2, 24)
  const horizontalFit = Math.floor(availW / 32)
  if (horizontalFit < Math.min(wanted, 5)) {
    return renderHourlyList(p, wanted)
  }
  return renderHourlyChart(p, Math.min(wanted, horizontalFit))
}

// An hour under its column, as a time ("09:00") where that fits the column,
// else its two digits ("09"): a bare 9 read as a column's number.
function hourLabel(hour, size, colW) {
  const hh = (hour < 10 ? '0' : '') + hour
  return textWidth(hh + ':00', size) <= colW * 0.92 ? hh + ':00' : hh
}

function renderHourlyChart(p, count) {
  const parts = []
  const series = hourlySeries(p.forecast, count)
  if (!series.length) {
    return renderMessage(p, label(p, 'noHourly'))
  }
  const h = headerSvg(p, label(p, 'nextHours').replace('{n}', series.length))
  parts.push(h.svg)

  const floor = hourlyFloor(p)
  const sides = sidesBetween(p, h.bottom, floor)
  const left = sides[0]
  const right = sides[1]
  const availW = right - left
  const colW = availW / series.length

  // The panel has two optional parts: the values row (icons + temperatures)
  // and the graph (temperature curve + precipitation bars).
  const showGraph = p.showGraph
  const showValues = p.showValues || !showGraph

  let iconSize = showValues ? clamp(colW * (showGraph ? 0.78 : 0.95), 15, showGraph ? 46 : 64) : 0
  let tempSize = showValues ? clamp(colW * (showGraph ? 0.34 : 0.4), 9, showGraph ? 20 : 24) : 0
  let rainy = false
  for (let i = 0; i < series.length; i++) {
    rainy = rainy || series[i].precip > 0.05
  }
  let rainLane = showGraph
  let precipH = rainLane ? clamp(p.H * 0.07, 8, 34) : 0

  // Use the full vertical band instead of centering a compact block. This keeps
  // portrait layouts from looking squeezed into the middle and gives rainfall
  // labels their own lane below the temperature curve.
  const topGap = p.base * 0.55
  const valuesGraphGap = showValues && showGraph ? clamp(p.base * 0.75, 10, 24) : 0
  let graphRainGap = rainLane ? clamp(p.base * 0.95, 12, 30) : 0
  let valuesH = showValues ? iconSize + tempSize * 1.45 : 0
  const timeH = clamp(p.base * 1.5, 14, 26)
  const availBand = Math.max(60, floor - h.bottom - topGap - timeH)
  const graphRoom = () => availBand - valuesH - valuesGraphGap - precipH - graphRainGap
  // A round panel, and a wide short one, has no height to spare: there the
  // rain lane is left out when none of these hours has rain to show, and the
  // icons sized by their columns shrink (to half at most) to leave the graph
  // its height, before the hours go off the bottom.
  const short = showGraph && (p.circle || graphRoom() < 44)
  if (short && !rainy) {
    rainLane = false
    precipH = 0
    graphRainGap = 0
  }
  const shortBy = short && showValues ? 28 - graphRoom() : 0
  if (shortBy > 0) {
    const k = Math.max(0.5, (valuesH - shortBy) / valuesH)
    iconSize *= k
    tempSize *= k
    valuesH *= k
  }
  const fixedH = valuesH + valuesGraphGap + (showGraph ? precipH + graphRainGap : 0)
  const chartH = showGraph ? Math.max(short ? 28 : 44, availBand - fixedH) : 0

  const iconTop = h.bottom + topGap
  const tempY = iconTop + iconSize + tempSize * 1.18
  const chartTop = iconTop + valuesH + valuesGraphGap
  const chartBottom = chartTop + chartH
  const rainTop = chartBottom + graphRainGap
  const bottom = rainTop + precipH

  // Temperature curve scale.
  let tMin = series[0].temp
  let tMax = series[0].temp
  let pMax = 0.4
  for (let i = 0; i < series.length; i++) {
    tMin = Math.min(tMin, series[i].temp)
    tMax = Math.max(tMax, series[i].temp)
    pMax = Math.max(pMax, series[i].precip)
  }
  if (tMax - tMin < 2) {
    tMax += 1
    tMin -= 1
  }
  const ys = []
  const xs = []
  for (let i = 0; i < series.length; i++) {
    xs.push(left + colW * (i + 0.5))
    ys.push(chartBottom - ((series[i].temp - tMin) / (tMax - tMin)) * (chartBottom - chartTop))
  }

  // Per-column icons, temps, precipitation bars and time labels. The first
  // temperature and the first precipitation value carry the units.
  const unit = (p.forecast.hourly_units || {}).temperature_2m || '°C'
  const precipUnit = ((p.forecast.hourly_units || {}).precipitation || 'mm').toUpperCase()
  const tempLabels = []
  let fittedTempSize = tempSize
  for (let i = 0; i < series.length; i++) {
    tempLabels.push(fmtTemp(series[i].temp))
    if (showValues) {
      fittedTempSize = Math.min(fittedTempSize, fitSize(tempLabels[i], tempSize, colW * 0.96))
    }
  }
  const dividerTop = showValues ? iconTop + iconSize * 0.2 : chartTop
  const labelSize = clamp(colW * 0.3, 8, 13)
  let precipLabeled = false
  for (let i = 0; i < series.length; i++) {
    const cx = xs[i]
    const item = series[i]
    if (showValues) {
      parts.push(iconFragment(p.icons, item.code, item.isDay, cx - iconSize / 2, iconTop, iconSize))
      parts.push(text(tempLabels[i], cx, tempY, fittedTempSize, p.theme.text, fittedTempSize * 0.13, 'middle'))
    }
    if (showGraph && item.precip > 0.05) {
      const bh = Math.max(2.5, (Math.min(item.precip, pMax) / pMax) * precipH)
      const bw = Math.max(3, colW * 0.24)
      const barTop = Math.max(rainTop, bottom - 2 - bh)
      parts.push(
        '<rect x="' + (cx - bw / 2).toFixed(2) + '" y="' + barTop.toFixed(2) + '" width="' + bw.toFixed(2) +
        '" height="' + bh.toFixed(2) + '" fill="' + p.theme.rain + '"/>'
      )
      const precipSize = clamp(colW * 0.24, 7, 10)
      let precipLabel = fmtPrecip(item.precip)
      if (!precipLabeled && textWidth(precipLabel + ' ' + precipUnit, precipSize) <= colW * 1.5) {
        precipLabel = precipLabel + ' ' + precipUnit
        precipLabeled = true
      }
      const precipY = Math.max(rainTop + precipSize, barTop - precipSize * 0.35)
      parts.push(text(precipLabel, cx, precipY, precipSize, p.theme.rain, precipSize * 0.13, 'middle'))
    }
    const isMidnight = item.hour === 0
    const label = isMidnight ? dayName(p.language, item.dow) : hourLabel(item.hour, labelSize, colW)
    parts.push(
      text(label, cx, bottom + timeH * 0.75, labelSize, isMidnight ? p.theme.text : p.theme.sub, labelSize * 0.12, 'middle')
    )
    if (isMidnight && i > 0) {
      const lx = left + colW * i
      parts.push(
        '<line x1="' + lx.toFixed(2) + '" y1="' + dividerTop.toFixed(2) + '" x2="' + lx.toFixed(2) +
        '" y2="' + bottom.toFixed(2) + '" stroke="' + p.theme.grid + '" stroke-width="1"/>'
      )
    }
  }

  if (!showGraph) {
    return parts.join('')
  }

  // Smooth temperature curve (Catmull-Rom converted to cubic beziers).
  let d = 'M ' + xs[0].toFixed(2) + ' ' + ys[0].toFixed(2)
  for (let i = 0; i < xs.length - 1; i++) {
    const x0 = i > 0 ? xs[i - 1] : xs[i]
    const y0 = i > 0 ? ys[i - 1] : ys[i]
    const x3 = i + 2 < xs.length ? xs[i + 2] : xs[i + 1]
    const y3 = i + 2 < ys.length ? ys[i + 2] : ys[i + 1]
    const c1x = xs[i] + (xs[i + 1] - x0) / 6
    const c1y = ys[i] + (ys[i + 1] - y0) / 6
    const c2x = xs[i + 1] - (x3 - xs[i]) / 6
    const c2y = ys[i + 1] - (y3 - ys[i]) / 6
    d += ' C ' + c1x.toFixed(2) + ' ' + c1y.toFixed(2) + ' ' + c2x.toFixed(2) + ' ' + c2y.toFixed(2) +
      ' ' + xs[i + 1].toFixed(2) + ' ' + ys[i + 1].toFixed(2)
  }
  if (p.theme.areaFill !== 'none') {
    const area = d + ' L ' + xs[xs.length - 1].toFixed(2) + ' ' + chartBottom.toFixed(2) +
      ' L ' + xs[0].toFixed(2) + ' ' + chartBottom.toFixed(2) + ' Z'
    parts.push('<path d="' + area + '" fill="' + p.theme.areaFill + '"/>')
  }
  const curveColor = p.theme.flat ? p.theme.line : tempColor((tMin + tMax) / 2, unit)
  parts.push(
    '<path d="' + d + '" fill="none" stroke="' + curveColor + '" stroke-width="' + clamp(colW * 0.06, 1.5, 3) +
    '" stroke-linecap="round"/>'
  )
  for (let i = 0; i < xs.length; i++) {
    parts.push('<circle cx="' + xs[i].toFixed(2) + '" cy="' + ys[i].toFixed(2) + '" r="' + clamp(colW * 0.07, 1.8, 3.4) + '" fill="' +
      (p.theme.flat ? p.theme.bgTop : curveColor) + '" stroke="' + (p.theme.flat ? p.theme.line : p.theme.text) + '" stroke-width="1.4"/>')
  }
  return parts.join('')
}

function renderHourlyList(p, wanted) {
  const parts = []
  const h = headerSvg(p, label(p, 'hourly'))
  parts.push(h.svg)
  const top = h.bottom + p.base * 0.3
  const availH = hourlyFloor(p) - top
  const sides = sidesBetween(p, top, top + availH)
  const L = sides[0]
  const listW = sides[1] - sides[0]
  const rowH = clamp(availH / wanted, 26, 54)
  const count = Math.max(1, Math.floor(availH / rowH))
  const series = hourlySeries(p.forecast, count)
  if (!series.length) {
    return renderMessage(p, label(p, 'noHourly'))
  }
  const size = clamp(rowH * 0.42, 9, 20)
  const unit = (p.forecast.hourly_units || {}).temperature_2m || '°C'
  const precipUnit = ((p.forecast.hourly_units || {}).precipitation || 'mm').toUpperCase()
  let precipLabeled = false
  for (let i = 0; i < series.length; i++) {
    const item = series[i]
    const midY = top + rowH * (i + 0.5)
    const baseY = midY + size * 0.36
    const label = item.hour === 0 ? dayName(p.language, item.dow) : (item.hour < 10 ? '0' : '') + item.hour + ':00'
    parts.push(text(label, L, baseY, size, p.theme.sub, size * 0.12, 'start'))
    parts.push(iconFragment(p.icons, item.code, item.isDay, L + listW * 0.33, midY - rowH * 0.42, rowH * 0.84))
    parts.push(
      text(fmtTemp(item.temp), L + listW * 0.65, baseY, size * 1.15, p.theme.text, size * 0.15, 'middle')
    )
    if (item.precip > 0.05) {
      const precipLabel = fmtPrecip(item.precip) + (precipLabeled ? '' : ' ' + precipUnit)
      precipLabeled = true
      parts.push(text(precipLabel, L + listW, baseY, size * 0.92, p.theme.rain, size * 0.11, 'end'))
    }
    if (i > 0) {
      parts.push(
        '<line x1="' + L.toFixed(2) + '" y1="' + (top + rowH * i).toFixed(2) + '" x2="' + (L + listW).toFixed(2) +
        '" y2="' + (top + rowH * i).toFixed(2) + '" stroke="' + p.theme.grid + '" stroke-width="1"/>'
      )
    }
  }
  return parts.join('')
}

// ---------------------------------------------------------------------------
// Daily forecast panel
// ---------------------------------------------------------------------------

function renderDaily(p) {
  const parts = []
  const h = headerSvg(p, label(p, 'daily'))
  parts.push(h.svg)
  const top = h.bottom + p.base * 0.3
  // On a round panel the rows keep to where the circle is 1.3 r wide or more.
  const availH = (p.circle ? Math.min(p.H - p.pad, p.circle.cy + p.circle.r * 0.75) : p.H - p.pad) - top
  const sides = sidesBetween(p, top, top + availH)
  const L = sides[0]
  const R = sides[1]
  const wanted = clamp(p.days, 1, 16)
  const rowH = clamp(availH / wanted, 26, 72)
  const count = Math.max(1, Math.min(wanted, Math.floor(availH / rowH)))
  const series = dailySeries(p.forecast, count)
  if (!series.length) {
    return renderMessage(p, label(p, 'noDaily'))
  }

  let tMin = series[0].min
  let tMax = series[0].max
  for (let i = 0; i < series.length; i++) {
    tMin = Math.min(tMin, series[i].min)
    tMax = Math.max(tMax, series[i].max)
  }
  if (tMax - tMin < 1) {
    tMax += 1
  }

  const unit = (p.forecast.daily_units || {}).temperature_2m_max || '°C'
  const size = clamp(rowH * 0.34, 9, 21)

  // Measured column budget: day | icon | (precip) | min | bar | max.
  const todayLabel = R - L + p.pad * 2 >= 380 ? label(p, 'today') : dayName(p.language, series[0].dow)
  const dayLabels = series.map((item, i) => (i === 0 ? todayLabel : dayName(p.language, item.dow)))
  let dayW = 0
  for (let i = 0; i < dayLabels.length; i++) {
    dayW = Math.max(dayW, textWidth(dayLabels[i], size))
  }
  dayW += size * 0.8
  const iconS = clamp(rowH * 0.78, 16, 48)
  const tempW = textWidth('-88°', size) + size * 0.6
  let precipW = R - L + p.pad * 2 >= 430 ? textWidth('88.8', size * 0.88) + size : 0
  let barLeft = L + dayW + iconS + precipW + tempW
  let barRight = R - tempW
  if (barRight - barLeft < p.W * 0.16) {
    precipW = 0
    barLeft = L + dayW + iconS + tempW
  }
  const scaleX = (t) => barLeft + ((t - tMin) / (tMax - tMin)) * (barRight - barLeft)

  for (let i = 0; i < series.length; i++) {
    const item = series[i]
    const midY = top + rowH * (i + 0.5)
    const baseY = midY + size * 0.36
    parts.push(text(dayLabels[i], L, baseY, size, p.theme.text, size * 0.13, 'start'))
    parts.push(iconFragment(p.icons, item.code, true, L + dayW, midY - iconS / 2, iconS))
    if (precipW > 0 && item.precip > 0.05) {
      parts.push(
        text(Math.round(item.precip * 10) / 10 + '', L + dayW + iconS + precipW * 0.85, baseY, size * 0.88, p.theme.rain, size * 0.1, 'end')
      )
    }
    parts.push(text(fmtTemp(item.min), barLeft - size * 0.7, baseY, size, p.theme.sub, size * 0.12, 'end'))
    parts.push(text(fmtTemp(item.max), barRight + size * 0.7, baseY, size, p.theme.text, size * 0.13, 'start'))

    // Temperature range bar on a shared scale.
    const x1 = scaleX(item.min)
    const x2 = Math.max(scaleX(item.max), x1 + 2)
    const bw = clamp(rowH * 0.18, 4, 10)
    if (p.theme.flat) {
      parts.push(
        '<line x1="' + x1.toFixed(2) + '" y1="' + midY.toFixed(2) + '" x2="' + x2.toFixed(2) + '" y2="' + midY.toFixed(2) +
        '" stroke="' + p.theme.barSolid + '" stroke-width="' + bw + '" stroke-linecap="round"/>'
      )
    } else {
      // Track + gradient bar built from butt-capped segments with round ends.
      parts.push(
        '<line x1="' + barLeft.toFixed(2) + '" y1="' + midY.toFixed(2) + '" x2="' + barRight.toFixed(2) + '" y2="' + midY.toFixed(2) +
        '" stroke="' + p.theme.grid + '" stroke-width="' + bw + '" stroke-linecap="round"/>'
      )
      const segments = 10
      for (let s = 0; s < segments; s++) {
        const t0 = s / segments
        const t1 = (s + 1) / segments
        const temp = item.min + (item.max - item.min) * ((t0 + t1) / 2)
        const sx1 = x1 + (x2 - x1) * t0
        const sx2 = x1 + (x2 - x1) * t1
        const isFirst = s === 0
        const isLast = s === segments - 1
        parts.push(
          '<line x1="' + (isFirst ? sx1 : sx1 - 0.4).toFixed(2) + '" y1="' + midY.toFixed(2) + '" x2="' + sx2.toFixed(2) +
          '" y2="' + midY.toFixed(2) + '" stroke="' + tempColor(temp, unit) + '" stroke-width="' + bw +
          '" stroke-linecap="' + (isFirst || isLast ? 'round' : 'butt') + '"/>'
        )
      }
    }
    if (i > 0) {
      parts.push(
        '<line x1="' + L.toFixed(2) + '" y1="' + (top + rowH * i).toFixed(2) + '" x2="' + R.toFixed(2) +
        '" y2="' + (top + rowH * i).toFixed(2) + '" stroke="' + p.theme.grid + '" stroke-width="1"/>'
      )
    }
  }
  return parts.join('')
}

// ---------------------------------------------------------------------------
// Fallbacks
// ---------------------------------------------------------------------------

function renderMessage(p, message) {
  return text(message, p.W / 2, p.H / 2, clamp(p.W * 0.05, 10, 24), p.theme.sub, 2, 'middle')
}

function renderErrorPanel(W, H, lowContrast, message, language) {
  const theme = themeFor(3, true, lowContrast)
  const panel = { W: W, H: H, theme: theme }
  const parts = [backgroundSvg(panel)]
  const size = clamp(Math.min(W, H) * 0.06, 10, 26)
  const labelContext = { language: language || 'en' }
  parts.push(text(label(labelContext, 'unavailable'), W / 2, H / 2 - size * 0.4, size, theme.text, size * 0.13, 'middle'))
  if (message) {
    const sub = ('' + message).substring(0, 60)
    parts.push(text(sub, W / 2, H / 2 + size * 1.4, size * 0.55, theme.sub, size * 0.07, 'middle'))
  }
  return parts.join('')
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

export function get(app: FrameOSApp, context: FrameOSContext) {
  let W = Number(app.config.width) || 0
  let H = Number(app.config.height) || 0
  if (W <= 0) {
    W = context.imageWidth || app.frame.width
  }
  if (H <= 0) {
    H = context.imageHeight || app.frame.height
  }

  const weather = app.config.weather
  const lowContrast = app.config.lowContrast === true
  let body
  if (!weather || weather.error || !weather.forecast) {
    body = renderErrorPanel(W, H, lowContrast, weather ? weather.error : 'no data', app.config.language || 'en')
  } else {
    const forecast = weather.forecast
    const cur = forecast.current_weather || {}
    // Kept outside the object literal: the FrameOS TS transpiler misreads
    // `key: value !== x` inside object literals as a type annotation.
    const showLocation = app.config.showLocation !== false
    const showDetails = app.config.showDetails !== false
    const showValues = app.config.showValues !== false
    const showGraph = app.config.showGraph !== false
    const p = {
      W: W,
      H: H,
      pad: clamp(Math.min(W, H) * 0.055, 8, 30),
      base: clamp(Math.min(W, H) * 0.052, 9, 24),
      weather: weather,
      forecast: forecast,
      icons: app.config.icons,
      theme: themeFor(cur.weathercode || 0, cur.is_day === 1, lowContrast),
      hours: Number(app.config.hours) || 10,
      days: Number(app.config.days) || 7,
      showLocation: showLocation,
      showDetails: showDetails,
      showValues: showValues,
      showGraph: showGraph,
      locationName: weather.location && weather.location.name ? weather.location.name : '',
      language: app.config.language || 'en',
      circle: roundCircle(app, context, W, H),
    }
    const mode = app.config.mode || 'current'
    if (mode === 'hourly') {
      body = backgroundSvg(p) + renderHourly(p)
    } else if (mode === 'daily') {
      body = backgroundSvg(p) + renderDaily(p)
    } else {
      body = backgroundSvg(p) + renderCurrent(p)
    }
  }

  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">' + body + '</svg>'
  return frameos.svg(svg, { width: W, height: H })
}

