// Open-Meteo weather data app.
// Fetches geocoding plus current, hourly and daily forecast data and returns
// the JSON shape consumed by the Weather panel app.

function asNumber(value, fallback) {
  const n = Number(value)
  return Number.isFinite(n) ? n : fallback
}

function clamp(value, min, max) {
  return value < min ? min : value > max ? max : value
}

function encodeQuery(value) {
  return encodeURIComponent('' + value)
}

function firstResult(response) {
  if (!response || !response.results || !response.results.length) {
    return null
  }
  return response.results[0]
}

function buildLocation(result, fallbackName) {
  const parts = []
  if (result && result.name) {
    parts.push(result.name)
  } else if (fallbackName) {
    parts.push(fallbackName)
  }
  if (result && result.admin1 && result.admin1 !== result.name) {
    parts.push(result.admin1)
  }
  if (result && result.country) {
    parts.push(result.country)
  }
  return {
    name: parts.join(', '),
    latitude: result ? result.latitude : null,
    longitude: result ? result.longitude : null,
    timezone: result ? result.timezone : '',
    country: result ? result.country : '',
    admin1: result ? result.admin1 : '',
  }
}

function forecastUrl(location, app) {
  const days = clamp(Math.round(asNumber(app.config.forecastDays, 7)), 1, 16)
  const temperatureUnit = app.config.temperatureUnit || 'celsius'
  const windSpeedUnit = app.config.windSpeedUnit || 'kmh'
  const precipitationUnit = app.config.precipitationUnit || 'mm'
  const params = [
    'latitude=' + location.latitude,
    'longitude=' + location.longitude,
    'timezone=auto',
    'forecast_days=' + days,
    'current_weather=true',
    'temperature_unit=' + encodeQuery(temperatureUnit),
    'wind_speed_unit=' + encodeQuery(windSpeedUnit),
    'precipitation_unit=' + encodeQuery(precipitationUnit),
    'hourly=' + [
      'temperature_2m',
      'apparent_temperature',
      'precipitation',
      'weathercode',
      'windspeed_10m',
    ].join(','),
    'daily=' + [
      'weathercode',
      'temperature_2m_max',
      'temperature_2m_min',
      'precipitation_sum',
      'sunrise',
      'sunset',
    ].join(','),
  ]
  return 'https://api.open-meteo.com/v1/forecast?' + params.join('&')
}

export function get(app: FrameOSApp) {
  const query = (app.config.location || '').trim()
  if (!query) {
    return { error: 'Missing location' }
  }

  try {
    const language = app.config.language || 'en'
    const geocodeUrl = 'https://geocoding-api.open-meteo.com/v1/search?name=' + encodeQuery(query) + '&count=1&language=' + encodeQuery(language) + '&format=json'
    const geocode = frameos.fetchJson(geocodeUrl)
    const result = firstResult(geocode)
    if (!result) {
      return { error: 'Location not found: ' + query }
    }

    const location = buildLocation(result, query)
    const forecast = frameos.fetchJson(forecastUrl(location, app))
    if (!forecast || forecast.error) {
      return { error: forecast && forecast.reason ? forecast.reason : 'Forecast unavailable', location: location }
    }

    return {
      location: location,
      forecast: forecast,
      date: forecast.current_weather && forecast.current_weather.time ? forecast.current_weather.time.substring(0, 10) : '',
      source: 'Open-Meteo',
    }
  } catch (error) {
    return { error: error && error.message ? error.message : '' + error }
  }
}
